// `access` and `compare` as `@solid-primitives/utils@7.0.0-next.4` declares
// them, with its `types.d.ts` helpers inlined. `accessOpen` is the control:
// the same declaration, with its contract's `callbacks` left open.
//
// The signatures are `tsc`-clean for every call `App.tsx` makes, so nothing
// here duplicates a type diagnostic.
type Accessor<T> = () => T;
type MaybeAccessor<T> = T | Accessor<T>;
type MaybeAccessorValue<T extends MaybeAccessor<any>> = T extends (() => any) ? ReturnType<T> : T;
export declare const access: <T extends MaybeAccessor<any>>(v: T) => MaybeAccessorValue<T>;
export declare const accessOpen: <T extends MaybeAccessor<any>>(v: T) => MaybeAccessorValue<T>;
export declare const compare: (a: any, b: any) => number;
